191	template <class TNode,class TLink>
192	void inline AddTail(TLink*apLink,TNode *ap)
193	{
194		if( ap->pLink )
195		{
196			return ;
197		}
198		if(apLink->tail)
199		{
200			apLink->tail->pNext = (TNode*)ap;
201			ap->pNext = NULL;
202			ap->pPrev = apLink->tail;
203			apLink->tail = ap;
204		}
205		else
206		{
207			apLink->head = apLink->tail = ap;
208			ap->pNext = ap->pPrev = NULL;
209		}
210		ap->pLink = apLink;
211	}
212	template <class TNode,class TLink>
213	void inline PopHead( TLink*apLink )
214	{
215		if( !apLink->head ) 
216		{
217			return ;
218		}
219		TNode *lp = apLink->head;
220		if( apLink->head == apLink->tail )
221		{
222			apLink->head = apLink->tail = NULL;
223		}
224		else
225		{
226			apLink->head = apLink->head->pNext;
227		}
228	
229		lp->pPrev = lp->pNext = NULL;
230		lp->pLink = NULL;
231	
232		if( apLink->head )
233		{
234			apLink->head->pPrev = NULL;
235		}
236	}
