618	void save_stack_buffer(stCoRoutine_t* occupy_co)
619	{
620		///copy out
621		stStackMem_t* stack_mem = occupy_co->stack_mem;
622		int len = stack_mem->stack_bp - occupy_co->stack_sp;
623	
624		if (occupy_co->save_buffer)
625		{
626			free(occupy_co->save_buffer), occupy_co->save_buffer = NULL;
627		}
628	
629		occupy_co->save_buffer = (char*)malloc(len); //malloc buf;
630		occupy_co->save_size = len;
631	
632		memcpy(occupy_co->save_buffer, occupy_co->stack_sp, len);
633	}
